function AuthModal({ onClose, onSuccess }: { onClose: () => void; onSuccess: () => void }) { const [mode, setMode] = useState<"signup" | "login">("signup"); const [loading, setLoading] = useState(false); const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [showPassword, setShowPassword] = useState(false); const [message, setMessage] = useState(""); const submit = async (event: React.FormEvent) => { event.preventDefault(); setLoading(true); setMessage(""); const result = mode === "signup" ? await supabase.auth.signUp({ email, password, options: { data: { full_name: name } } }) : await supabase.auth.signInWithPassword({ email, password }); if (result.error) setMessage(result.error.message); else if (mode === "signup" && !result.data.session) setMessage("Account created. Sign in with your email and passcode."); else onSuccess(); setLoading(false); }; return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/85 p-4 backdrop-blur-sm"><Card className="w-full max-w-md border-white/10 bg-[#17142c] p-7 shadow-[0_20px_70px_rgba(141,128,217,.18)]"><div className="flex items-start justify-between"><div><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#8d80d9] text-slate-950"><Wallet className="h-5 w-5" /></div><h2 className="mt-5 text-2xl font-semibold text-white">{mode === "signup" ? "Create your vault" : "Welcome back"}</h2><p className="mt-1 text-sm text-slate-400">{mode === "signup" ? "Join KovaWealth to fund and manage your assets." : "Sign in to access your wallet."}</p></div><button onClick={onClose} className="text-slate-500 hover:text-white"><X className="h-5 w-5" /></button></div><form onSubmit={submit} className="mt-6 space-y-4">{mode === "signup" && <label className="block text-sm text-slate-300">Full name<Input required className="mt-2 h-11 border-slate-700 bg-slate-900 text-white" placeholder="{displayName}" value={name} onChange={event => setName(event.target.value)} /></label>}<label className="block text-sm text-slate-300">Email address<Input required type="email" className="mt-2 h-11 border-slate-700 bg-slate-900 text-white" placeholder="you@example.com" value={email} onChange={event => setEmail(event.target.value)} /></label><label className="block text-sm text-slate-300">Passcode<Input required minLength={8} type={showPassword ? "text" : "password"} className="mt-2 h-11 border-slate-700 bg-slate-900 text-white" placeholder="8+ characters" value={password} onChange={event => setPassword(event.target.value)} /><label className="mt-2 flex items-center gap-2 text-xs text-slate-500"><input type="checkbox" checked={showPassword} onChange={event => setShowPassword(event.target.checked)} className="accent-[#8d80d9]" />Show password</label></label><Button disabled={loading} className="h-11 w-full bg-[#8d80d9] font-semibold text-white hover:bg-[#a79be7]">{loading ? "Opening your vault..." : mode === "signup" ? "Create free account" : "Sign in"}</Button></form>{message && <p className="mt-4 text-center text-sm text-amber-300">{message}</p>}<p className="mt-5 text-center text-sm text-slate-500">{mode === "signup" ? "Already have an account?" : "New to KovaWealth?"} <button type="button" onClick={() => setMode(mode === "signup" ? "login" : "signup")} className="font-medium text-[#a79be7]">{mode === "signup" ? "Sign in" : "Create an account"}</button></p><p className="mt-5 text-center text-[11px] text-slate-600">By continuing, you agree to our Terms and Privacy Policy.</p></Card></div>; }

